package br.com.mecaniQA.api.Mappers;
import java.sql.*; import br.com.mecaniQA.api.model.*; import br.com.mecaniQA.api.Enums.*;
public class OrdemServicoResultSetMapper implements ResultSetMapper<OrdemServico>{public OrdemServico map(ResultSet r)throws SQLException{Cliente c=new Cliente();c.setIdCliente(r.getLong("id_cliente"));Veiculo v=new Veiculo();v.setIdVeiculo(r.getLong("id_veiculo"));v.setCliente(c);String d=r.getString("descricao_problema");OrdemServico x=OrdemServico.builder().comCliente(c).comVeiculo(v).comDescricaoProblema(d==null||d.isBlank()?"Descrição não informada":d).comStatus(StatusOrdemServico.valueOf(r.getString("status"))).comObservacoes(r.getString("observacoes")).comValorTotal(r.getDouble("valor_total")).build();x.setNumeroOS(r.getLong("numero_os"));Timestamp a=r.getTimestamp("data_atualizacao"),f=r.getTimestamp("data_finalizacao");x.setDataAtualizacao(a==null?null:a.toLocalDateTime());x.setDataFinalizacao(f==null?null:f.toLocalDateTime());return x;}}
